import './ui/styles/main.css';
import { Game } from './core/game';

/** Boot: everything is generated by code at runtime; no network, no asset files. */
const BOOT_FADE_MS = 900;
const DEMO_AUTOSTART_MS = 1500;
/** The loading screen stays at least this long so its progress bar reads as loading, not a flash. */
const BOOT_MIN_MS = 1600;

/** Waits for the browser to paint (so the loading screen shows before the heavy build). */
const nextFrame = (): Promise<void> => new Promise((r) => requestAnimationFrame(() => r()));

async function boot(): Promise<void> {
  const stage = document.getElementById('stage');
  const ui = document.getElementById('ui');
  const screen = document.getElementById('boot');
  if (!stage || !ui) return;
  const shownAt = performance.now();
  await nextFrame();
  await nextFrame();
  const game = Game.start(stage, ui);
  const params = new URLSearchParams(location.search);
  if (!screen) return;
  if (!game || params.has('debug') || params.has('skipintro')) {
    screen.remove();
    return;
  }
  await new Promise((r) => window.setTimeout(r, Math.max(0, BOOT_MIN_MS - (performance.now() - shownAt))));
  screen.classList.add('ready');
  let started = false;
  const begin = (): void => {
    if (started) return;
    started = true;
    screen.classList.add('gone');
    window.setTimeout(() => screen.remove(), BOOT_FADE_MS);
    game.playIntro(params.has('demo'));
  };
  screen.querySelector('.go')?.addEventListener('click', begin);
  window.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') begin(); });
  if (params.has('demo')) window.setTimeout(begin, DEMO_AUTOSTART_MS);
}

void boot();
